def base(p,t,A):
    return p[0]/t + p[1]*A/(1+p[2]*A)*t**3 + p[3]*np.sin(p[4]*np.sqrt(A))*t**1.5
fams={
 'te*Af*exp(-dA)': (lambda t,A,q: t**q[0]*A**q[2]*np.exp(-q[1]*A), 3),
 'te*exp(-dA^2)': (lambda t,A,q: t**q[0]*np.exp(-q[1]*A**2), 2),
}
for name,(f,nq) in fams.items():
    best=None
    for s in range(120):
        rng=np.random.default_rng(s)
        p0=np.concatenate([rng.normal(0,1,5),[rng.normal(0,0.3),rng.uniform(0,1),rng.normal(0,0.5)][:nq] if nq==3 else [rng.normal(0,0.3),rng.uniform(0,1)]])
        p0[5]=rng.normal(0,2)
        p0=np.concatenate([p0[:5],[p0[5]],p0[6:]])
        try:
            r=least_squares(lambda p: base(p[:5],t,A)+p[5]*f(t,A,p[6:6+nq])-dA_dt, p0, bounds=(np.r_[-np.inf*np.ones(5),-np.inf,-3*np.ones(nq)], np.r_[np.inf*np.ones(5),np.inf,3*np.ones(nq)]))
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    if best is not None: print(name, np.round(best.x,4), float(np.var(best.fun)/np.var(dA_dt)))
    else: print(name,'failed')
